package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.ApiResponse; import in.kabadiwala.connect.integration.StorageService; import in.kabadiwala.connect.service.DocumentService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; @RestController @RequestMapping("/api/v1") public class FileController {private final DocumentService docs;private final StorageService storage;public FileController(DocumentService d,StorageService s){docs=d;storage=s;} @PostMapping(value="/files",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) ApiResponse<?> upload(Authentication a,@RequestParam String purpose,@RequestPart MultipartFile file){return ApiResponse.ok("Uploaded",docs.upload(a.getName(),purpose,file));} @GetMapping("/files/**") ResponseEntity<byte[]> read(jakarta.servlet.http.HttpServletRequest req){String key=req.getRequestURI().substring("/api/v1/files/".length());return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).body(storage.read(key));}}
